#define CL_TARGET_OPENCL_VERSION 300
#include <CL/cl.h>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <iterator>
#include <string>
#include <vector>
#define CK(x) do { cl_int mask_status = (x); if (mask_status != CL_SUCCESS) { fprintf(stderr, "OpenCL %d at line %d: %s\n", mask_status, __LINE__, #x); return 2; } } while (0)
int main(int argc, char ** argv){if(argc!=3){fprintf(stderr,"Usage: %s BUGGY_FIXTURE CURRENT_KERNEL\n",argv[0]);return 1;}cl_uint np;CK(clGetPlatformIDs(0,nullptr,&np));std::vector<cl_platform_id>ps(np);CK(clGetPlatformIDs(np,ps.data(),nullptr));cl_device_id d=nullptr;for(auto p:ps){cl_uint n=0;if(clGetDeviceIDs(p,CL_DEVICE_TYPE_GPU,1,&d,&n)==0&&n)break;d=nullptr;}if(!d)return 1;cl_int err;auto c=clCreateContext(nullptr,1,&d,nullptr,nullptr,&err);CK(err);auto q=clCreateCommandQueue(c,d,0,&err);CK(err);int fixed_failures=0,baseline_failures=0;
 for(int mode=0;mode<2;mode++){std::ifstream f(argv[mode ? 2 : 1]);std::string source((std::istreambuf_iterator<char>(f)),{});const char*s=source.c_str();auto p=clCreateProgramWithSource(c,1,&s,nullptr,&err);CK(err);CK(clBuildProgram(p,1,&d,"-cl-std=CL3.0 -cl-mad-enable -cl-unsafe-math-optimizations -cl-finite-math-only -cl-fast-relaxed-math",nullptr,nullptr));auto k=clCreateKernel(p,"kernel_diag_mask_inf_8",&err);CK(err);
 for(int cols:{8,16,24,32,64})for(int past:{0,3,17}){int rows=7,heads=3;size_t count=cols*rows*heads;const int guard=64;std::vector<float>src(count+guard*2,12345),out(src.size(),-12345),expected=out;for(size_t i=0;i<count;i++)src[guard+i]=float(i%997)/113;for(int h=0;h<heads;h++)for(int r=0;r<rows;r++)for(int col=0;col<cols;col++){size_t i=(h*rows+r)*cols+col;expected[guard+i]=col>past+r?-INFINITY:src[guard+i];}auto a=clCreateBuffer(c,CL_MEM_READ_ONLY|CL_MEM_COPY_HOST_PTR,src.size()*4,src.data(),&err);CK(err);auto b=clCreateBuffer(c,CL_MEM_READ_WRITE|CL_MEM_COPY_HOST_PTR,out.size()*4,out.data(),&err);CK(err);cl_ulong offset=guard*4;CK(clSetKernelArg(k,0,sizeof(a),&a));CK(clSetKernelArg(k,1,sizeof(offset),&offset));CK(clSetKernelArg(k,2,sizeof(b),&b));CK(clSetKernelArg(k,3,sizeof(offset),&offset));CK(clSetKernelArg(k,4,sizeof(cols),&cols));CK(clSetKernelArg(k,5,sizeof(rows),&rows));CK(clSetKernelArg(k,6,sizeof(past),&past));size_t g=count/8,l=64;CK(clEnqueueNDRangeKernel(q,k,1,nullptr,&g,&l,0,nullptr,nullptr));CK(clEnqueueReadBuffer(q,b,CL_TRUE,0,out.size()*4,out.data(),0,nullptr,nullptr));size_t mismatch=0,corrupt=0;for(size_t i=0;i<out.size();i++){bool equal=out[i]==expected[i];if(!equal){mismatch++;if(i<guard||i>=guard+count)corrupt++;}}printf("RESULT {\"variant\":\"%s\",\"cols\":%d,\"past\":%d,\"rows\":%d,\"heads\":%d,\"wrong_values\":%zu,\"guard_corruptions\":%zu}\n",mode?"fixed":"baseline",cols,past,rows,heads,mismatch,corrupt);fflush(stdout);if(mode)fixed_failures+=mismatch>0;else baseline_failures+=mismatch>0;CK(clReleaseMemObject(a));CK(clReleaseMemObject(b));}CK(clReleaseKernel(k));CK(clReleaseProgram(p));}
 printf("SUMMARY baseline_failed=%d fixed_failed=%d\n",baseline_failures,fixed_failures);CK(clReleaseCommandQueue(q));CK(clReleaseContext(c));return fixed_failures||baseline_failures==0?2:0;}
